import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { PageLayout } from "@/components/layout/PageLayout";
import { ClockSV } from "@/components/ClockSV";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { BarChart3, Check, ClipboardCheck, Eye, FileText, Grid2X2, Pencil, Play, Plus, Printer, Search, SlidersHorizontal, Trash2, X } from "lucide-react";
import {
  InventoryItem, InventoryMovement, InventoryCountSession, InventorySupplier, PurchaseOrder, applyInventoryCount, cancelInventoryCount,
  createInventoryAdjustment, createInventoryCount, createInventoryItem, deleteInventoryCount, downloadInventoryPdf, finalizeInventoryCount,
  getRuntimeFeatureSettings, getInventoryCount, getInventoryCounts, getInventoryItems, getInventoryMovements, getInventoryReportAdjustments,
  getInventoryReportCounts, getInventorySuppliers, getPurchaseOrders, saveInventorySupplier, deleteInventorySupplier,
  savePurchaseOrder, approvePurchaseOrder, cancelPurchaseOrder, receivePurchaseOrder, updateInventoryCountLines, updateInventoryItem,
} from "@/lib/api";

const UNITS = ["unidad", "docena", "media_docena", "caja_25", "caja_50", "caja_75", "caja_100", "libra", "media_libra", "onza", "kilogramo", "gramo", "litro", "mililitro", "bolsa", "paquete", "rollo", "bandeja", "botella", "lata"].map((value) => ({ value, label: value.replaceAll("_", " ").replace(/^./, (c) => c.toUpperCase()) }));
const UNIT_LABEL_BY_VALUE = Object.fromEntries(UNITS.map((unit) => [unit.value, unit.label]));
const ITEM_FILTERS = ["Todos", "Stock bajo", "Activos", "Inactivos"] as const;
const MOVEMENT_FILTERS = ["Todos", "Entradas", "Pérdidas", "Dañados", "Correcciones", "Conteos", "Ventas"] as const;
const BASIC_TABS = ["Dashboard", "Ajustar", "Recontar", "Reportes"] as const;
const ADVANCED_TABS = ["Proveedores", "Costos", "Órdenes de compra"] as const;
const TAB_ICONS: Record<string, typeof Grid2X2> = { Dashboard: Grid2X2, Ajustar: SlidersHorizontal, Recontar: ClipboardCheck, Reportes: BarChart3, Proveedores: Grid2X2, Costos: BarChart3, "Órdenes de compra": ClipboardCheck };
const IconOnly = ({ label, children, onClick, disabled, variant = "outline" }: { label: string; children: ReactNode; onClick?: () => void; disabled?: boolean; variant?: "default" | "outline" | "destructive" }) => <Button size="icon" variant={variant} title={label} aria-label={label} onClick={onClick} disabled={disabled} className="h-8 w-8">{children}</Button>;
const REPORT_TABS = ["Ajustes", "Conteos"] as const;
const ADJUSTMENT_OPTIONS = [
  { value: "entry", label: "Entrada de producto", description: "Aumenta el stock cuando ingresan productos al inventario." },
  { value: "loss", label: "Pérdida", description: "Descuenta productos perdidos del inventario." },
  { value: "damaged", label: "Producto dañado", description: "Descuenta productos que ya no pueden utilizarse o venderse." },
  { value: "correction", label: "Corrección de stock", description: "Fija el stock real después de una revisión física." },
] as const;
type AdjustmentType = typeof ADJUSTMENT_OPTIONS[number]["value"];

const MOVEMENT_LABELS: Record<string, string> = {
  initial_stock: "Stock inicial", stock_add: "Entrada de producto", stock_adjustment: "Corrección de stock", inventory_entry: "Entrada de producto",
  inventory_loss: "Pérdida", inventory_damaged: "Producto dañado", inventory_correction: "Corrección de stock", inventory_count_adjustment: "Ajuste por conteo",
  sale_deduction: "Descuento por venta", reversal: "Reversión", purchase_receipt: "Entrada por orden de compra",
};
const COUNT_STATUS_BADGE: Record<string, string> = { draft: "Borrador", in_progress: "En progreso", finalized: "Finalizado", applied: "Aplicado", cancelled: "Cancelado" };
const COUNT_TYPE_LABEL: Record<string, string> = { complete: "Conteo completo", manual: "Conteo manual", category: "Por categoría" };
const formatQuantity = (value: number | null | undefined): string => value == null || Number.isNaN(value) ? "—" : value.toLocaleString("es-SV", { maximumFractionDigits: 3 });
const isLowStock = (item: InventoryItem) => item.minStock != null && item.currentStock < item.minStock;
const parseOptionalNumber = (value: string) => (value.trim() === "" ? null : Number(value));
const dateOnly = () => new Date().toISOString().slice(0, 10);

export default function InventoryPage() {
  const [tab, setTab] = useState<string>("Dashboard");
  const [advancedEnabled, setAdvancedEnabled] = useState(false);
  const [query, setQuery] = useState("");
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [movements, setMovements] = useState<InventoryMovement[]>([]);
  const [counts, setCounts] = useState<InventoryCountSession[]>([]);
  const [openForm, setOpenForm] = useState(false);
  const [editing, setEditing] = useState<InventoryItem | null>(null);
  const [itemFilter, setItemFilter] = useState<(typeof ITEM_FILTERS)[number]>("Todos");
  const [movementFilter, setMovementFilter] = useState<(typeof MOVEMENT_FILTERS)[number]>("Todos");
  const [openAdjustment, setOpenAdjustment] = useState(false);
  const [lockedAdjustmentItem, setLockedAdjustmentItem] = useState(false);
  const [openCountDialog, setOpenCountDialog] = useState(false);
  const [activeCount, setActiveCount] = useState<InventoryCountSession | null>(null);
  const [selectedMovement, setSelectedMovement] = useState<InventoryMovement | null>(null);
  const [reportTab, setReportTab] = useState<(typeof REPORT_TABS)[number]>("Ajustes");
  const [reportAdjustments, setReportAdjustments] = useState<InventoryMovement[]>([]);
  const [reportCounts, setReportCounts] = useState<InventoryCountSession[]>([]);
  const [reportFilters, setReportFilters] = useState({ dateFrom: "", dateTo: "", inventoryItem: "", movementType: "", status: "", countType: "" });

  const [name, setName] = useState(""); const [sku, setSku] = useState(""); const [unit, setUnit] = useState("unidad"); const [stock, setStock] = useState(""); const [minStock, setMinStock] = useState(""); const [maxStock, setMaxStock] = useState(""); const [notes, setNotes] = useState(""); const [active, setActive] = useState(true);
  const [supplierId, setSupplierId] = useState(""); const [unitCost, setUnitCost] = useState(""); const [supplierCode, setSupplierCode] = useState(""); const [purchaseUnit, setPurchaseUnit] = useState(""); const [purchaseFactor, setPurchaseFactor] = useState("1"); const [suppliers, setSuppliers] = useState<InventorySupplier[]>([]);
  const [adjustItemId, setAdjustItemId] = useState(""); const [adjustType, setAdjustType] = useState<AdjustmentType>("entry"); const [adjustQuantity, setAdjustQuantity] = useState(""); const [adjustSetStock, setAdjustSetStock] = useState(""); const [adjustReason, setAdjustReason] = useState("");
  const [countType, setCountType] = useState<"complete" | "manual">("complete"); const [countNotes, setCountNotes] = useState(""); const [manualCountSearch, setManualCountSearch] = useState(""); const [selectedCountItemIds, setSelectedCountItemIds] = useState<number[]>([]); const [countDraftLines, setCountDraftLines] = useState<Record<number, { countedStock: string; note: string }>>({});
  const nameInputRef = useRef<HTMLInputElement | null>(null);

  const load = async (q = query) => {
    const [rows, logs, countRows] = await Promise.all([getInventoryItems(q), getInventoryMovements(), getInventoryCounts()]);
    setItems(rows); setMovements(logs); setCounts(countRows);
  };
  useEffect(() => { load().catch(() => toast.error("No se pudo cargar inventario")); getRuntimeFeatureSettings().then((settings) => setAdvancedEnabled(settings.inventoryAdvancedEnabled)).catch(() => setAdvancedEnabled(false)); getInventorySuppliers(undefined, true).then(setSuppliers).catch(() => setSuppliers([])); }, []);
  useEffect(() => { if (!openForm) return; const t = window.setTimeout(() => nameInputRef.current?.focus(), 30); return () => window.clearTimeout(t); }, [openForm]);

  const resetForm = () => { setName(""); setSku(""); setUnit("unidad"); setStock(""); setMinStock(""); setMaxStock(""); setSupplierId(""); setUnitCost(""); setSupplierCode(""); setPurchaseUnit(""); setPurchaseFactor("1"); setNotes(""); setActive(true); setEditing(null); };
  const openAdjustmentModal = (item?: InventoryItem) => { setAdjustItemId(item ? String(item.id) : ""); setLockedAdjustmentItem(Boolean(item)); setAdjustType("entry"); setAdjustQuantity(""); setAdjustSetStock(""); setAdjustReason(""); setOpenAdjustment(true); setTab("Ajustar"); };
  const selectedAdjustmentItem = useMemo(() => items.find((item) => String(item.id) === adjustItemId) ?? null, [adjustItemId, items]);
  const estimatedFinalStock = useMemo(() => { if (!selectedAdjustmentItem) return null; const current = selectedAdjustmentItem.currentStock; if (adjustType === "correction") return adjustSetStock.trim() === "" ? current : Number(adjustSetStock); const qty = Number(adjustQuantity || 0); return adjustType === "entry" ? current + qty : current - qty; }, [adjustQuantity, adjustSetStock, adjustType, selectedAdjustmentItem]);
  const filtered = useMemo(() => items.filter((i) => i.name.toLowerCase().includes(query.toLowerCase()) || i.sku.toLowerCase().includes(query.toLowerCase())).filter((i) => itemFilter === "Todos" || (itemFilter === "Stock bajo" && isLowStock(i)) || (itemFilter === "Activos" && i.isActive) || (itemFilter === "Inactivos" && !i.isActive)), [items, query, itemFilter]);
  const filteredMovements = useMemo(() => movements.filter((m) => { const type = m.movementType; if (movementFilter === "Todos") return true; if (movementFilter === "Entradas") return ["initial_stock", "stock_add", "inventory_entry", "purchase_receipt"].includes(type); if (movementFilter === "Pérdidas") return type === "inventory_loss"; if (movementFilter === "Dañados") return type === "inventory_damaged"; if (movementFilter === "Correcciones") return ["stock_adjustment", "inventory_correction"].includes(type); if (movementFilter === "Conteos") return type === "inventory_count_adjustment"; return type === "sale_deduction"; }), [movements, movementFilter]);
  const manualCountItems = useMemo(() => items.filter((item) => `${item.name} ${item.sku}`.toLowerCase().includes(manualCountSearch.toLowerCase())), [items, manualCountSearch]);
  const printCount = async (session: InventoryCountSession) => { const detail = session.lines ? session : await getInventoryCount(session.id); printHtml(`Conteo ${detail.code}`, tableHtml((detail.lines ?? []).map((line) => [line.inventoryItemName, line.inventoryItemSku || "—", line.inventoryItemUnit, formatQuantity(line.systemStock), formatQuantity(line.countedStock), formatQuantity(line.difference), line.note || "—"]))); };

  const saveAdjustment = async () => { if (!selectedAdjustmentItem) return toast.error("Selecciona un artículo."); const quantity = Number(adjustQuantity || 0); const realStock = Number(adjustSetStock || 0); if (adjustType !== "correction" && quantity <= 0) return toast.error("La cantidad debe ser mayor a 0."); if (adjustType === "correction" && (adjustSetStock.trim() === "" || realStock < 0)) return toast.error("El stock real debe ser mayor o igual a 0."); if (["loss", "damaged", "correction"].includes(adjustType) && !adjustReason.trim()) return toast.error("El motivo es obligatorio para este ajuste."); if (["loss", "damaged"].includes(adjustType) && quantity > selectedAdjustmentItem.currentStock) return toast.error("La cantidad no puede ser mayor al stock disponible."); try { await createInventoryAdjustment({ inventoryItem: selectedAdjustmentItem.id, adjustmentType: adjustType, quantity: adjustType === "correction" ? undefined : quantity, setStock: adjustType === "correction" ? realStock : undefined, reason: adjustReason }); await load(query); setOpenAdjustment(false); toast.success("Ajuste registrado correctamente."); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo registrar el ajuste"); } };

  const startCount = async () => { if (countType === "manual" && selectedCountItemIds.length === 0) { toast.error("Selecciona al menos un artículo para el conteo manual."); return; } try { const session = await createInventoryCount({ countType, notes: countNotes, itemIds: selectedCountItemIds }); setActiveCount(session); setCountDraftLines(Object.fromEntries((session.lines ?? []).map((line) => [line.id, { countedStock: line.countedStock == null ? "" : String(line.countedStock), note: line.note }]))); setOpenCountDialog(false); await load(query); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo crear el conteo"); } };
  const openCount = async (session: InventoryCountSession) => { try { const detail = await getInventoryCount(session.id); setActiveCount(detail); setCountDraftLines(Object.fromEntries((detail.lines ?? []).map((line) => [line.id, { countedStock: line.countedStock == null ? "" : String(line.countedStock), note: line.note }]))); } catch { toast.error("No se pudo abrir el conteo"); } };
  const saveCountDraft = async () => { if (!activeCount) return; const lines = (activeCount.lines ?? []).map((line) => ({ id: line.id, countedStock: countDraftLines[line.id]?.countedStock === "" ? null : Number(countDraftLines[line.id]?.countedStock ?? 0), note: countDraftLines[line.id]?.note ?? "" })); try { const updated = await updateInventoryCountLines(activeCount.id, lines); setActiveCount(updated); await load(query); toast.success("Borrador guardado"); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo guardar el conteo"); } };
  const finalizeCount = async () => { if (!activeCount) return; await saveCountDraft(); try { const updated = await finalizeInventoryCount(activeCount.id); setActiveCount(updated); await load(query); toast.success("Conteo finalizado"); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo finalizar"); } };
  const applyCount = async (session = activeCount) => { if (!session) return; if (!window.confirm("Esta acción actualizará el stock del inventario y creará movimientos de ajuste por conteo. ¿Deseas continuar?")) return; try { const result = await applyInventoryCount(session.id); setActiveCount(result.session); await load(query); toast.success("Diferencias aplicadas correctamente."); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudieron aplicar diferencias"); } };
  const cancelCount = async (session: InventoryCountSession) => { if (!window.confirm("¿Cancelar este conteo? No se modificará el inventario.")) return; try { const updated = await cancelInventoryCount(session.id, "Cancelado desde inventario"); if (activeCount?.id === session.id) setActiveCount(updated); await load(query); toast.success("Conteo cancelado"); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo cancelar"); } };
  const deleteCount = async (session: InventoryCountSession) => { if (!window.confirm(`¿Eliminar el conteo ${session.code}? Esta acción no se puede deshacer.`)) return; try { await deleteInventoryCount(session.id); if (activeCount?.id === session.id) setActiveCount(null); await load(query); await loadReports(); toast.success("Conteo eliminado"); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo eliminar el conteo"); } };
  const loadReports = async () => { const filters = { dateFrom: reportFilters.dateFrom || undefined, dateTo: reportFilters.dateTo || undefined, inventoryItem: reportFilters.inventoryItem ? Number(reportFilters.inventoryItem) : undefined, movementType: reportFilters.movementType || undefined, status: reportFilters.status || undefined, countType: reportFilters.countType || undefined }; const [adjustments, countRows] = await Promise.all([getInventoryReportAdjustments(filters), getInventoryReportCounts(filters)]); setReportAdjustments(adjustments); setReportCounts(countRows); };
  useEffect(() => { loadReports().catch(() => undefined); }, []);

  const printHtml = (title: string, html: string) => { const win = window.open("", "_blank", "width=1100,height=800"); if (!win) return; win.document.write(`<html><head><title>${title}</title><style>body{font-family:sans-serif;padding:24px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #bbb;padding:6px;font-size:12px}th{background:#166534;color:white}</style></head><body><h1>${title}</h1>${html}</body></html>`); win.document.close(); win.print(); };
  const adjustmentPdfUrl = () => { const params = new URLSearchParams(); if (reportFilters.dateFrom) params.set("date_from", reportFilters.dateFrom); if (reportFilters.dateTo) params.set("date_to", reportFilters.dateTo); if (reportFilters.inventoryItem) params.set("inventory_item", reportFilters.inventoryItem); if (reportFilters.movementType) params.set("movement_type", reportFilters.movementType); return `/inventory/reports/adjustments/pdf/${params.toString() ? `?${params.toString()}` : ""}`; };

  return (
    <PageLayout title="Inventario" subtitle="Control simple, rápido y totalmente integrado." actions={<ClockSV timeClassName="text-2xl sm:text-3xl" className="min-w-[220px]" />}>
      <div className="space-y-4">
        <div className="flex flex-wrap gap-2">{[...BASIC_TABS, ...(advancedEnabled ? ADVANCED_TABS : [])].map((next) => { const Icon = TAB_ICONS[next]; return <Button key={next} variant={tab === next ? "default" : "outline"} onClick={() => setTab(next)} title={next} aria-label={next} className="gap-2"><Icon className="h-4 w-4" /><span className="hidden sm:inline">{next}</span></Button>; })}</div>
        {tab === "Dashboard" ? <>
          <div className="mx-auto flex w-full max-w-5xl flex-col items-stretch gap-3 sm:flex-row sm:items-center"><Input placeholder="Buscar por nombre o código" value={query} onChange={(e) => setQuery(e.target.value)} className="h-12 flex-1" /><Button className="h-12 gap-2 px-4" variant="outline" title="Recontar inventario" aria-label="Recontar inventario" onClick={() => setOpenCountDialog(true)}><ClipboardCheck className="h-4 w-4" /><span className="hidden sm:inline">Recontar</span></Button><Button className="h-12 gap-2 px-4" variant="outline" title="Ajustar inventario" aria-label="Ajustar inventario" onClick={() => openAdjustmentModal()}><SlidersHorizontal className="h-4 w-4" /><span className="hidden sm:inline">Ajustar</span></Button><Button className="h-12 gap-2 px-4" title="Nuevo artículo" aria-label="Nuevo artículo" onClick={() => { resetForm(); setOpenForm(true); }}><Plus className="h-4 w-4" /><span className="hidden sm:inline">Nuevo</span></Button></div>
          <div className="mx-auto flex w-full max-w-5xl flex-wrap gap-2">{ITEM_FILTERS.map((filter) => <Button key={filter} size="sm" variant={itemFilter === filter ? "default" : "outline"} onClick={() => setItemFilter(filter)}>{filter}</Button>)}</div>
          <InventoryItemsTable items={filtered} onEdit={(item) => { setEditing(item); setName(item.name); setSku(item.sku); setUnit(item.unit); setMinStock(item.minStock == null || Number(item.minStock) === 0 ? "" : String(item.minStock)); setMaxStock(item.maxStock == null || Number(item.maxStock) === 0 ? "" : String(item.maxStock)); setSupplierId(item.supplier ? String(item.supplier) : ""); setUnitCost(item.unitCost ? String(item.unitCost) : ""); setSupplierCode(item.supplierCode ?? ""); setPurchaseUnit(item.purchaseUnit ?? ""); setPurchaseFactor(item.purchaseToInventoryFactor ? String(item.purchaseToInventoryFactor) : "1"); setNotes(item.notes ?? ""); setActive(item.isActive); setOpenForm(true); }} onAdjust={openAdjustmentModal} />
          <RecentMovements movements={filteredMovements} movementFilter={movementFilter} setMovementFilter={setMovementFilter} />
        </> : null}
        {tab === "Ajustar" ? <div className="rounded-xl border bg-card p-4"><div className="flex items-center justify-between"><div><h3 className="text-lg font-semibold">Ajustar inventario</h3><p className="text-sm text-muted-foreground">Registra entradas, pérdidas, dañados o correcciones manuales.</p></div><Button onClick={() => openAdjustmentModal()} className="gap-2" title="Ajustar inventario" aria-label="Ajustar inventario"><SlidersHorizontal className="h-4 w-4" /><span>Ajustar</span></Button></div><RecentMovements movements={filteredMovements} movementFilter={movementFilter} setMovementFilter={setMovementFilter} /></div> : null}
        {tab === "Recontar" ? <div className="space-y-4"><div className="flex items-center justify-between rounded-xl border bg-card p-4"><div><h3 className="text-lg font-semibold">Recontar inventario</h3><p className="text-sm text-muted-foreground">Crea sesiones de conteo físico, guarda borradores, finaliza y aplica diferencias.</p></div><Button onClick={() => setOpenCountDialog(true)} className="gap-2" title="Nuevo conteo" aria-label="Nuevo conteo"><Plus className="h-4 w-4" /><span>Nuevo</span></Button></div><CountsTable counts={counts} onOpen={(session) => void openCount(session)} onApply={applyCount} onCancel={cancelCount} onDelete={deleteCount} onPdf={(row) => downloadInventoryPdf(`/inventory/reports/counts/${row.id}/pdf/`, `conteo-inventario-${row.code}.pdf`)} onPrint={(row) => void printCount(row)} /></div> : null}
        {tab === "Reportes" ? <div className="space-y-4"><div className="flex flex-wrap gap-2">{REPORT_TABS.map((next) => <Button key={next} variant={reportTab === next ? "default" : "outline"} onClick={() => setReportTab(next)}>{next}</Button>)}</div><ReportFilters items={items} filters={reportFilters} setFilters={setReportFilters} onSearch={loadReports} reportTab={reportTab} />{reportTab === "Ajustes" ? <AdjustmentsReport rows={reportAdjustments} onDetail={setSelectedMovement} onPdf={() => downloadInventoryPdf(adjustmentPdfUrl(), `reporte-ajustes-inventario-${dateOnly()}.pdf`)} onPrint={() => printHtml("Reporte de Ajustes de Inventario", tableHtml(reportAdjustments.map((m) => [new Date(m.createdAt).toLocaleString(), m.inventoryItemName, MOVEMENT_LABELS[m.movementType] ?? m.movementType, formatQuantity(m.quantityChange), formatQuantity(m.quantityBefore), formatQuantity(m.quantityAfter), m.createdByUsername || "—", m.reason || "—"])))} /> : <CountsReport rows={reportCounts} onOpen={(session) => void openCount(session)} onPdf={(row) => downloadInventoryPdf(`/inventory/reports/counts/${row.id}/pdf/`, `conteo-inventario-${row.code}.pdf`)} onPrint={(row) => void printCount(row)}/>}</div> : null}
        {advancedEnabled && tab === "Proveedores" ? <SuppliersPanel suppliers={suppliers} reload={() => getInventorySuppliers(undefined, true).then(setSuppliers)} /> : null}
        {advancedEnabled && tab === "Costos" ? <CostsPanel items={items} suppliers={suppliers} reload={() => load(query)} /> : null}
        {advancedEnabled && tab === "Órdenes de compra" ? <PurchaseOrdersPanel items={items} suppliers={suppliers} reloadInventory={() => load(query)} printHtml={printHtml} /> : null}
      </div>
      <Dialog open={openForm} onOpenChange={setOpenForm}><DialogContent className="max-w-xl"><DialogHeader><DialogTitle>{editing ? "Editar" : "Nuevo"} artículo de inventario</DialogTitle></DialogHeader><div className="grid gap-3"><Label>Código/SKU</Label><Input value={sku} onChange={(e) => setSku(e.target.value)} className="h-11" /><Label>Nombre</Label><Input ref={nameInputRef} value={name} onChange={(e) => setName(e.target.value)} className="h-11" /><Label>Unidad</Label><Select value={unit} onValueChange={setUnit}><SelectTrigger className="h-11"><SelectValue /></SelectTrigger><SelectContent>{UNITS.map((u) => <SelectItem key={u.value} value={u.value}>{u.label}</SelectItem>)}</SelectContent></Select>{!editing ? <><Label>Stock inicial</Label><Input type="number" placeholder="0" value={stock} onChange={(e) => setStock(e.target.value)} className="h-11" /></> : null}<div className="grid gap-3 sm:grid-cols-2"><div className="space-y-2"><Label>Stock mínimo</Label><Input type="number" placeholder="0" value={minStock} onChange={(e) => setMinStock(e.target.value)} /></div><div className="space-y-2"><Label>Stock máximo</Label><Input type="number" placeholder="0" value={maxStock} onChange={(e) => setMaxStock(e.target.value)} /></div></div>{advancedEnabled ? <div className="space-y-3 rounded-xl border bg-muted/20 p-3"><h4 className="font-semibold">Datos avanzados</h4><div className="grid gap-3 sm:grid-cols-2"><div className="space-y-2"><Label>Proveedor</Label><Select value={supplierId || "__none"} onValueChange={(v) => setSupplierId(v === "__none" ? "" : v)}><SelectTrigger><SelectValue placeholder="Proveedor" /></SelectTrigger><SelectContent><SelectItem value="__none">Sin proveedor</SelectItem>{suppliers.map((supplier) => <SelectItem key={supplier.id} value={String(supplier.id)}>{supplier.name}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Costo por unidad</Label><Input type="number" placeholder="0" value={unitCost} onChange={(e) => setUnitCost(e.target.value)} /></div><div className="space-y-2"><Label>Código de proveedor</Label><Input value={supplierCode} onChange={(e) => setSupplierCode(e.target.value)} /></div><div className="space-y-2"><Label>Unidad de compra</Label><Input placeholder="Caja" value={purchaseUnit} onChange={(e) => setPurchaseUnit(e.target.value)} /></div><div className="space-y-2"><Label>Factor compra → inventario</Label><Input type="number" min="0.0001" step="0.0001" placeholder="1" value={purchaseFactor} onChange={(e) => setPurchaseFactor(e.target.value)} /></div></div></div> : null}<Label>Notas</Label><Textarea value={notes} onChange={(e) => setNotes(e.target.value)} /><Label className="flex items-center gap-2"><input type="checkbox" checked={active} onChange={(e)=>setActive(e.target.checked)} /> Activo</Label><Button className="h-11" onClick={async () => { try { const payload = { name, sku, unit, minStock: parseOptionalNumber(minStock), maxStock: parseOptionalNumber(maxStock), supplier: supplierId ? Number(supplierId) : null, unitCost: parseOptionalNumber(unitCost), supplierCode, purchaseUnit, purchaseToInventoryFactor: Number(purchaseFactor || 1), notes, isActive: active }; if (editing) await updateInventoryItem(editing.id, payload); else await createInventoryItem({ ...payload, initialStock: Number(stock || 0) }); await load(query); setOpenForm(false); toast.success("Inventario guardado"); } catch { toast.error("No se pudo guardar"); } }}>Guardar</Button></div></DialogContent></Dialog>
      <Dialog open={openAdjustment} onOpenChange={setOpenAdjustment}><DialogContent className="max-w-2xl"><DialogHeader><DialogTitle>Ajustar inventario</DialogTitle></DialogHeader><div className="space-y-4"><div className="space-y-2"><Label>Artículo</Label><Select value={adjustItemId} onValueChange={setAdjustItemId} disabled={lockedAdjustmentItem}><SelectTrigger><SelectValue placeholder="Selecciona un artículo" /></SelectTrigger><SelectContent>{items.map((item) => <SelectItem key={item.id} value={String(item.id)}>{item.name} · Stock {formatQuantity(item.currentStock)}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Tipo de ajuste</Label><div className="grid gap-2 sm:grid-cols-2">{ADJUSTMENT_OPTIONS.map((option) => <button key={option.value} type="button" className={cn("rounded-xl border p-3 text-left", adjustType === option.value ? "border-primary bg-primary/10" : "hover:bg-muted/40")} onClick={() => setAdjustType(option.value)}><p className="font-semibold">{option.label}</p><p className="text-xs text-muted-foreground">{option.description}</p></button>)}</div></div>{adjustType === "correction" ? <><Label>Stock real</Label><Input type="number" placeholder="0" value={adjustSetStock} onChange={(e) => setAdjustSetStock(e.target.value)} /></> : <><Label>Cantidad</Label><Input type="number" placeholder="0" value={adjustQuantity} onChange={(e)=>setAdjustQuantity(e.target.value)} /></>}<Label>Motivo/nota{adjustType === "entry" ? "" : " (obligatorio)"}</Label><Textarea value={adjustReason} onChange={(e)=>setAdjustReason(e.target.value)} /><div className="grid gap-2 rounded-xl border bg-muted/20 p-3 text-sm sm:grid-cols-3"><div><p className="text-muted-foreground">Stock actual</p><p className="font-semibold">{formatQuantity(selectedAdjustmentItem?.currentStock)}</p></div><div><p className="text-muted-foreground">Cambio</p><p className="font-semibold">{selectedAdjustmentItem ? formatQuantity((estimatedFinalStock ?? selectedAdjustmentItem.currentStock) - selectedAdjustmentItem.currentStock) : "—"}</p></div><div><p className="text-muted-foreground">Stock final estimado</p><p className="font-semibold">{formatQuantity(estimatedFinalStock)}</p></div></div><Button className="w-full" onClick={() => void saveAdjustment()}>Guardar ajuste</Button></div></DialogContent></Dialog>
      <Dialog open={openCountDialog} onOpenChange={setOpenCountDialog}><DialogContent className="max-w-3xl"><DialogHeader><DialogTitle>Recontar inventario</DialogTitle></DialogHeader><div className="space-y-4"><div className="grid gap-2 sm:grid-cols-2"><button className={cn("rounded-xl border p-3 text-left", countType === "complete" && "border-primary bg-primary/10")} onClick={() => setCountType("complete")}><p className="font-semibold">Conteo completo</p><p className="text-xs text-muted-foreground">Agrega todos los artículos activos del inventario.</p></button><button className={cn("rounded-xl border p-3 text-left", countType === "manual" && "border-primary bg-primary/10")} onClick={() => setCountType("manual")}><p className="font-semibold">Conteo manual</p><p className="text-xs text-muted-foreground">Selecciona manualmente los artículos que deseas contar.</p></button><button disabled className="rounded-xl border p-3 text-left opacity-50"><p className="font-semibold">Por categoría</p><p className="text-xs text-muted-foreground">Disponible próximamente.</p></button><button disabled className="rounded-xl border p-3 text-left opacity-50"><p className="font-semibold">Por proveedor</p><p className="text-xs text-muted-foreground">Disponible en Inventario Avanzado.</p></button></div>{countType === "manual" ? <div className="space-y-2 rounded-xl border p-3"><div className="flex flex-col gap-2 sm:flex-row"><Input placeholder="Buscar artículos" value={manualCountSearch} onChange={(e) => setManualCountSearch(e.target.value)} /><Button type="button" variant="outline" onClick={() => setSelectedCountItemIds((prev) => Array.from(new Set([...prev, ...manualCountItems.map((item) => item.id)])))}>Seleccionar visibles</Button></div><p className="text-sm text-muted-foreground">Artículos seleccionados: {selectedCountItemIds.length}</p><div className="max-h-52 overflow-auto">{manualCountItems.map((item) => <Label key={item.id} className="flex items-center gap-2 py-1"><input type="checkbox" checked={selectedCountItemIds.includes(item.id)} onChange={(e) => setSelectedCountItemIds((prev) => e.target.checked ? [...prev, item.id] : prev.filter((id) => id !== item.id))} /> {item.name} · {item.sku || "Sin código"}</Label>)}{manualCountItems.length === 0 ? <p className="py-4 text-center text-sm text-muted-foreground">No hay artículos para la búsqueda.</p> : null}</div></div> : <p className="rounded-xl border p-3 text-sm text-muted-foreground">Se incluirán todos los artículos activos.</p>}<Label>Notas</Label><Textarea value={countNotes} onChange={(e) => setCountNotes(e.target.value)} /><Button onClick={() => void startCount()} disabled={countType === "manual" && selectedCountItemIds.length === 0}>Crear conteo</Button></div></DialogContent></Dialog>
      {activeCount ? <Dialog open={Boolean(activeCount)} onOpenChange={(open) => !open && setActiveCount(null)}><DialogContent className="max-h-[90vh] max-w-6xl overflow-auto"><DialogHeader><DialogTitle>Conteo físico {activeCount.code}</DialogTitle></DialogHeader><div className="space-y-4"><div className="grid gap-2 rounded-xl border bg-muted/20 p-3 text-sm sm:grid-cols-3"><div><p className="text-muted-foreground">Código/ID</p><p className="font-semibold">{activeCount.code}</p></div><div><p className="text-muted-foreground">Tipo</p><p className="font-semibold">{COUNT_TYPE_LABEL[activeCount.countType] ?? activeCount.countType}</p></div><div><p className="text-muted-foreground">Usuario</p><p className="font-semibold">{activeCount.createdByUsername || "—"}</p></div><div><p className="text-muted-foreground">Fecha</p><p className="font-semibold">{new Date(activeCount.createdAt).toLocaleString()}</p></div><div className="sm:col-span-2"><p className="text-muted-foreground">Notas</p><p className="font-semibold">{activeCount.notes || "—"}</p></div></div><CountSummary session={activeCount} /><div className="max-h-[520px] overflow-auto"><Table><TableHeader><TableRow><TableHead>Artículo</TableHead><TableHead>Código</TableHead><TableHead>Unidad</TableHead><TableHead>Stock sistema</TableHead><TableHead>Conteo físico</TableHead><TableHead>Diferencia</TableHead><TableHead>Nota</TableHead></TableRow></TableHeader><TableBody>{(activeCount.lines ?? []).map((line) => { const draft = countDraftLines[line.id] ?? { countedStock: line.countedStock == null ? "" : String(line.countedStock), note: line.note }; const diff = draft.countedStock === "" ? null : Number(draft.countedStock) - line.systemStock; const editable = ["draft", "in_progress"].includes(activeCount.status); return <TableRow key={line.id}><TableCell>{line.inventoryItemName}</TableCell><TableCell>{line.inventoryItemSku || "—"}</TableCell><TableCell>{UNIT_LABEL_BY_VALUE[line.inventoryItemUnit] ?? line.inventoryItemUnit}</TableCell><TableCell>{formatQuantity(line.systemStock)}</TableCell><TableCell>{editable ? <Input type="number" placeholder="0" className="h-9" value={draft.countedStock} onChange={(e) => setCountDraftLines((prev) => ({ ...prev, [line.id]: { ...draft, countedStock: e.target.value } }))} /> : formatQuantity(line.countedStock)}</TableCell><TableCell className={cn(diff != null && diff > 0 && "text-emerald-500", diff != null && diff < 0 && "text-red-500")}>{diff == null ? "Pendiente" : formatQuantity(diff)}</TableCell><TableCell>{editable ? <Input className="h-9" value={draft.note} onChange={(e) => setCountDraftLines((prev) => ({ ...prev, [line.id]: { ...draft, note: e.target.value } }))} /> : line.note || "—"}</TableCell></TableRow>; })}</TableBody></Table></div><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => void saveCountDraft()} disabled={!['draft','in_progress'].includes(activeCount.status)}>Guardar borrador</Button><Button onClick={() => void finalizeCount()} disabled={!['draft','in_progress'].includes(activeCount.status)}>Finalizar conteo</Button><Button onClick={() => void applyCount()} disabled={activeCount.status !== "finalized"}>Aplicar diferencias</Button><Button variant="destructive" onClick={() => void cancelCount(activeCount)} disabled={activeCount.status === "applied"}>Cancelar</Button><Button variant="destructive" onClick={() => void deleteCount(activeCount)} disabled={activeCount.status === "applied" || activeCount.status === "finalized"}>Eliminar</Button><Button variant="outline" onClick={() => downloadInventoryPdf(`/inventory/reports/counts/${activeCount.id}/pdf/`, `conteo-inventario-${activeCount.code}.pdf`)}>Descargar PDF</Button></div></div></DialogContent></Dialog> : null}
      {selectedMovement ? <Dialog open={Boolean(selectedMovement)} onOpenChange={(open) => !open && setSelectedMovement(null)}><DialogContent className="max-w-xl"><DialogHeader><DialogTitle>Detalle de ajuste</DialogTitle></DialogHeader><div className="grid gap-2 text-sm sm:grid-cols-2"><div><p className="text-muted-foreground">Fecha/hora</p><p className="font-semibold">{new Date(selectedMovement.createdAt).toLocaleString()}</p></div><div><p className="text-muted-foreground">Artículo</p><p className="font-semibold">{selectedMovement.inventoryItemName}</p></div><div><p className="text-muted-foreground">Código/SKU</p><p className="font-semibold">{selectedMovement.inventoryItemSku || "—"}</p></div><div><p className="text-muted-foreground">Unidad</p><p className="font-semibold">{selectedMovement.inventoryItemUnit || "—"}</p></div><div><p className="text-muted-foreground">Tipo</p><p className="font-semibold">{MOVEMENT_LABELS[selectedMovement.movementType] ?? selectedMovement.movementType}</p></div><div><p className="text-muted-foreground">Cantidad modificada</p><p className="font-semibold">{formatQuantity(selectedMovement.quantityChange)}</p></div><div><p className="text-muted-foreground">Stock anterior</p><p className="font-semibold">{formatQuantity(selectedMovement.quantityBefore)}</p></div><div><p className="text-muted-foreground">Stock nuevo</p><p className="font-semibold">{formatQuantity(selectedMovement.quantityAfter)}</p></div><div><p className="text-muted-foreground">Usuario</p><p className="font-semibold">{selectedMovement.createdByUsername || "—"}</p></div><div><p className="text-muted-foreground">Referencia</p><p className="font-semibold">{selectedMovement.referenceType ? `${selectedMovement.referenceType}:${selectedMovement.referenceId}` : "—"}</p></div><div className="sm:col-span-2"><p className="text-muted-foreground">Motivo</p><p className="font-semibold">{selectedMovement.reason || "—"}</p></div></div></DialogContent></Dialog> : null}
    </PageLayout>
  );
}

const tableHtml = (rows: Array<Array<string | number>>) => `<table><tbody>${rows.map((row) => `<tr>${row.map((cell) => `<td>${String(cell)}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
function InventoryItemsTable({ items, onEdit, onAdjust }: { items: InventoryItem[]; onEdit: (item: InventoryItem) => void; onAdjust: (item: InventoryItem) => void }) { return <div className="rounded-xl border bg-card"><Table><TableHeader><TableRow><TableHead>Producto</TableHead><TableHead>Código</TableHead><TableHead>Unidad</TableHead><TableHead>Stock</TableHead><TableHead>Mínimo</TableHead><TableHead>Máximo</TableHead><TableHead>Estado</TableHead><TableHead>Acciones</TableHead></TableRow></TableHeader><TableBody>{items.map((item) => { const low = isLowStock(item); return <TableRow key={item.id} className={cn(low && "border-l-2 border-l-red-500/80 bg-red-500/5")}><TableCell className="font-semibold">{item.name}</TableCell><TableCell>{item.sku || "—"}</TableCell><TableCell>{UNIT_LABEL_BY_VALUE[item.unit] ?? item.unit}</TableCell><TableCell className={cn("font-semibold", low && "text-red-500")}>{formatQuantity(item.currentStock)}</TableCell><TableCell>{formatQuantity(item.minStock)}</TableCell><TableCell>{formatQuantity(item.maxStock)}</TableCell><TableCell><div className="flex flex-wrap gap-1"><Badge variant={item.isActive ? "default" : "outline"}>{item.isActive ? "Activo" : "Inactivo"}</Badge>{low ? <Badge className="bg-red-600 text-white">Stock bajo</Badge> : null}</div></TableCell><TableCell className="space-x-2"><IconOnly label="Editar" onClick={() => onEdit(item)}><Pencil className="h-4 w-4" /></IconOnly><IconOnly label="Ajustar inventario" onClick={() => onAdjust(item)}><SlidersHorizontal className="h-4 w-4" /></IconOnly></TableCell></TableRow>; })}</TableBody></Table></div>; }
function RecentMovements({ movements, movementFilter, setMovementFilter }: { movements: InventoryMovement[]; movementFilter: (typeof MOVEMENT_FILTERS)[number]; setMovementFilter: (value: (typeof MOVEMENT_FILTERS)[number]) => void }) { return <div className="rounded-xl border bg-card p-4"><div className="mb-3 flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between"><h3 className="text-lg font-semibold">Movimientos recientes</h3><div className="flex flex-wrap gap-2">{MOVEMENT_FILTERS.map((filter) => <Button key={filter} size="sm" variant={movementFilter === filter ? "default" : "outline"} onClick={() => setMovementFilter(filter)}>{filter}</Button>)}</div></div><div className="max-h-[320px] overflow-auto"><Table><TableHeader><TableRow><TableHead>Fecha</TableHead><TableHead>Producto</TableHead><TableHead>Tipo</TableHead><TableHead>Cambio</TableHead><TableHead>Antes</TableHead><TableHead>Después</TableHead><TableHead>Usuario</TableHead><TableHead>Motivo</TableHead></TableRow></TableHeader><TableBody>{movements.map((m) => <TableRow key={m.id}><TableCell>{new Date(m.createdAt).toLocaleString()}</TableCell><TableCell>{m.inventoryItemName}</TableCell><TableCell>{MOVEMENT_LABELS[m.movementType] ?? m.movementType}</TableCell><TableCell>{formatQuantity(m.quantityChange)}</TableCell><TableCell>{formatQuantity(m.quantityBefore)}</TableCell><TableCell>{formatQuantity(m.quantityAfter)}</TableCell><TableCell>{m.createdByUsername || "—"}</TableCell><TableCell>{m.reason || "—"}</TableCell></TableRow>)}</TableBody></Table></div></div>; }
function CountSummary({ session }: { session: InventoryCountSession }) { const pending = session.totalItems - session.countedItems; return <div className="grid gap-2 rounded-xl border bg-muted/20 p-3 text-sm sm:grid-cols-6"><div><p className="text-muted-foreground">Estado</p><p className="font-semibold">{COUNT_STATUS_BADGE[session.status] ?? session.status}</p></div><div><p className="text-muted-foreground">Artículos</p><p className="font-semibold">{session.totalItems}</p></div><div><p className="text-muted-foreground">Contados</p><p className="font-semibold">{session.countedItems}</p></div><div><p className="text-muted-foreground">Pendientes</p><p className="font-semibold">{pending}</p></div><div><p className="text-muted-foreground">Dif. positivas</p><p className="font-semibold text-emerald-500">{formatQuantity(session.totalPositiveDifferences)}</p></div><div><p className="text-muted-foreground">Dif. negativas</p><p className="font-semibold text-red-500">{formatQuantity(session.totalNegativeDifferences)}</p></div></div>; }
function CountsTable({ counts, onOpen, onApply, onCancel, onDelete, onPdf, onPrint }: { counts: InventoryCountSession[]; onOpen: (s: InventoryCountSession) => void; onApply: (s: InventoryCountSession) => void; onCancel: (s: InventoryCountSession) => void; onDelete: (s: InventoryCountSession) => void; onPdf: (s: InventoryCountSession) => void; onPrint: (s: InventoryCountSession) => void }) { return <div className="rounded-xl border bg-card"><Table><TableHeader><TableRow><TableHead>Fecha</TableHead><TableHead>Código/ID</TableHead><TableHead>Tipo</TableHead><TableHead>Estado</TableHead><TableHead>Usuario</TableHead><TableHead>Artículos</TableHead><TableHead>Diferencias</TableHead><TableHead>Acciones</TableHead></TableRow></TableHeader><TableBody>{counts.map((row) => <TableRow key={row.id}><TableCell>{new Date(row.createdAt).toLocaleString()}</TableCell><TableCell>{row.code}</TableCell><TableCell>{COUNT_TYPE_LABEL[row.countType] ?? row.countType}</TableCell><TableCell><Badge>{COUNT_STATUS_BADGE[row.status] ?? row.status}</Badge></TableCell><TableCell>{row.createdByUsername || "—"}</TableCell><TableCell>{row.countedItems}/{row.totalItems}</TableCell><TableCell>{row.totalDifferences}</TableCell><TableCell className="space-x-2"><IconOnly label={["draft","in_progress"].includes(row.status) ? "Continuar" : "Ver detalle"} onClick={() => onOpen(row)}>{["draft","in_progress"].includes(row.status) ? <Play className="h-4 w-4" /> : <Eye className="h-4 w-4" />}</IconOnly><IconOnly label="Aplicar diferencias" onClick={() => onApply(row)} disabled={row.status !== "finalized"} variant="default"><Check className="h-4 w-4" /></IconOnly><IconOnly label="Descargar PDF" onClick={() => onPdf(row)} disabled={row.status === "cancelled"}><FileText className="h-4 w-4" /></IconOnly><IconOnly label="Imprimir" onClick={() => onPrint(row)} disabled={row.status === "cancelled"}><Printer className="h-4 w-4" /></IconOnly><IconOnly label="Cancelar" onClick={() => onCancel(row)} disabled={row.status === "applied" || row.status === "cancelled"} variant="destructive"><X className="h-4 w-4" /></IconOnly><IconOnly label="Eliminar" onClick={() => onDelete(row)} disabled={row.status === "applied" || row.status === "finalized"} variant="destructive"><Trash2 className="h-4 w-4" /></IconOnly></TableCell></TableRow>)}{counts.length === 0 ? <TableRow><TableCell colSpan={8} className="py-8 text-center text-muted-foreground">No hay conteos registrados todavía.</TableCell></TableRow> : null}</TableBody></Table></div>; }
function ReportFilters({ items, filters, setFilters, onSearch, reportTab }: { items: InventoryItem[]; filters: any; setFilters: (v: any) => void; onSearch: () => void; reportTab: string }) { return <div className="rounded-xl border bg-card p-3"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div className="space-y-1"><Label>Fecha desde</Label><Input type="date" className="h-10" value={filters.dateFrom} onChange={(e) => setFilters((p: any) => ({ ...p, dateFrom: e.target.value }))} /></div><div className="space-y-1"><Label>Fecha hasta</Label><Input type="date" className="h-10" value={filters.dateTo} onChange={(e) => setFilters((p: any) => ({ ...p, dateTo: e.target.value }))} /></div><div className="space-y-1"><Label>Artículo</Label><Select value={filters.inventoryItem || "__all"} onValueChange={(v) => setFilters((p: any) => ({ ...p, inventoryItem: v === "__all" ? "" : v }))}><SelectTrigger className="h-10"><SelectValue placeholder="Artículo" /></SelectTrigger><SelectContent><SelectItem value="__all">Todos los artículos</SelectItem>{items.map((item) => <SelectItem key={item.id} value={String(item.id)}>{item.name}</SelectItem>)}</SelectContent></Select></div>{reportTab === "Ajustes" ? <div className="space-y-1"><Label>Tipo de movimiento</Label><Select value={filters.movementType || "__all"} onValueChange={(v) => setFilters((p: any) => ({ ...p, movementType: v === "__all" ? "" : v }))}><SelectTrigger className="h-10"><SelectValue placeholder="Tipo" /></SelectTrigger><SelectContent><SelectItem value="__all">Todos</SelectItem>{Object.entries(MOVEMENT_LABELS).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div> : <><div className="space-y-1"><Label>Estado</Label><Select value={filters.status || "__all"} onValueChange={(v) => setFilters((p: any) => ({ ...p, status: v === "__all" ? "" : v }))}><SelectTrigger className="h-10"><SelectValue placeholder="Estado" /></SelectTrigger><SelectContent><SelectItem value="__all">Todos</SelectItem>{Object.entries(COUNT_STATUS_BADGE).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div><div className="space-y-1"><Label>Tipo de conteo</Label><Select value={filters.countType || "__all"} onValueChange={(v) => setFilters((p: any) => ({ ...p, countType: v === "__all" ? "" : v }))}><SelectTrigger className="h-10"><SelectValue placeholder="Tipo" /></SelectTrigger><SelectContent><SelectItem value="__all">Todos</SelectItem>{Object.entries(COUNT_TYPE_LABEL).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div></>}</div><div className="mt-3 flex flex-wrap gap-2"><Button onClick={onSearch} size="sm" className="gap-2" title="Buscar"><Search className="h-4 w-4" />Buscar</Button><Button variant="outline" size="sm" title="Limpiar filtros" aria-label="Limpiar filtros" onClick={() => { setFilters({ dateFrom: "", dateTo: "", inventoryItem: "", movementType: "", status: "", countType: "" }); setTimeout(onSearch, 0); }}><X className="h-4 w-4" /></Button></div></div>; }
function AdjustmentsReport({ rows, onDetail, onPdf, onPrint }: { rows: InventoryMovement[]; onDetail: (m: InventoryMovement) => void; onPdf: () => void; onPrint: () => void }) { return <div className="rounded-xl border bg-card p-4"><div className="mb-3 flex justify-between"><h3 className="text-lg font-semibold">Reporte de ajustes</h3><div className="space-x-2"><Button variant="outline" onClick={onPdf}>Descargar PDF</Button><Button variant="outline" onClick={onPrint}>Imprimir</Button></div></div><Table><TableHeader><TableRow><TableHead>Fecha</TableHead><TableHead>Artículo</TableHead><TableHead>Tipo</TableHead><TableHead>Cambio</TableHead><TableHead>Stock anterior</TableHead><TableHead>Stock nuevo</TableHead><TableHead>Usuario</TableHead><TableHead>Motivo</TableHead><TableHead>Acciones</TableHead></TableRow></TableHeader><TableBody>{rows.map((m) => <TableRow key={m.id}><TableCell>{new Date(m.createdAt).toLocaleString()}</TableCell><TableCell>{m.inventoryItemName}</TableCell><TableCell>{MOVEMENT_LABELS[m.movementType] ?? m.movementType}</TableCell><TableCell>{formatQuantity(m.quantityChange)}</TableCell><TableCell>{formatQuantity(m.quantityBefore)}</TableCell><TableCell>{formatQuantity(m.quantityAfter)}</TableCell><TableCell>{m.createdByUsername || "—"}</TableCell><TableCell>{m.reason || "—"}</TableCell><TableCell><IconOnly label="Ver detalle" onClick={() => onDetail(m)}><Eye className="h-4 w-4" /></IconOnly></TableCell></TableRow>)}{rows.length === 0 ? <TableRow><TableCell colSpan={9} className="py-8 text-center text-muted-foreground">No hay movimientos para los filtros seleccionados.</TableCell></TableRow> : null}</TableBody></Table></div>; }
function CountsReport({ rows, onOpen, onPdf, onPrint }: { rows: InventoryCountSession[]; onOpen: (s: InventoryCountSession) => void; onPdf: (s: InventoryCountSession) => void; onPrint: (s: InventoryCountSession) => void }) { return <div className="rounded-xl border bg-card p-4"><h3 className="mb-3 text-lg font-semibold">Reporte de conteos</h3><Table><TableHeader><TableRow><TableHead>Fecha</TableHead><TableHead>Código/ID</TableHead><TableHead>Tipo</TableHead><TableHead>Estado</TableHead><TableHead>Usuario</TableHead><TableHead>Artículos contados</TableHead><TableHead>Diferencias</TableHead><TableHead>Aplicado en</TableHead><TableHead>Acciones</TableHead></TableRow></TableHeader><TableBody>{rows.map((row) => <TableRow key={row.id}><TableCell>{new Date(row.createdAt).toLocaleString()}</TableCell><TableCell>{row.code}</TableCell><TableCell>{COUNT_TYPE_LABEL[row.countType] ?? row.countType}</TableCell><TableCell><Badge>{COUNT_STATUS_BADGE[row.status] ?? row.status}</Badge></TableCell><TableCell>{row.createdByUsername || "—"}</TableCell><TableCell>{row.countedItems}/{row.totalItems}</TableCell><TableCell>{row.totalDifferences}</TableCell><TableCell>{row.appliedAt ? new Date(row.appliedAt).toLocaleString() : "—"}</TableCell><TableCell className="space-x-2"><IconOnly label="Ver detalle" onClick={() => onOpen(row)}><Eye className="h-4 w-4" /></IconOnly><IconOnly label="Descargar PDF" onClick={() => onPdf(row)}><FileText className="h-4 w-4" /></IconOnly><IconOnly label="Imprimir" onClick={() => onPrint(row)}><Printer className="h-4 w-4" /></IconOnly></TableCell></TableRow>)}{rows.length === 0 ? <TableRow><TableCell colSpan={9} className="py-8 text-center text-muted-foreground">No hay reportes de conteo para los filtros seleccionados.</TableCell></TableRow> : null}</TableBody></Table></div>; }

type SupplierDraft = { id?: number; name: string; code: string; contactName: string; phone: string; email: string; address: string; taxId: string; notes: string; isActive: boolean };
const emptySupplierDraft = (): SupplierDraft => ({ name: "", code: "", contactName: "", phone: "", email: "", address: "", taxId: "", notes: "", isActive: true });

function SuppliersPanel({ suppliers, reload }: { suppliers: InventorySupplier[]; reload: () => Promise<void> }) {
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState<SupplierDraft>(emptySupplierDraft());
  const filtered = suppliers.filter((supplier) => `${supplier.name} ${supplier.code} ${supplier.phone} ${supplier.email}`.toLowerCase().includes(query.toLowerCase()));
  const edit = (supplier?: InventorySupplier) => { setDraft(supplier ? { id: supplier.id, name: supplier.name, code: supplier.code ?? "", contactName: supplier.contactName ?? "", phone: supplier.phone ?? "", email: supplier.email ?? "", address: supplier.address ?? "", taxId: supplier.taxId ?? "", notes: supplier.notes ?? "", isActive: supplier.isActive } : emptySupplierDraft()); setOpen(true); };
  const save = async () => { if (!draft.name.trim()) return toast.error("El nombre del proveedor es obligatorio."); if (draft.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(draft.email)) return toast.error("Correo inválido."); await saveInventorySupplier(draft); toast.success("Proveedor guardado."); setOpen(false); await reload(); };
  const remove = async (supplier: InventorySupplier) => { await deleteInventorySupplier(supplier.id); toast.success("Proveedor desactivado o eliminado."); await reload(); };
  return <div className="space-y-4"><div className="flex flex-col gap-2 rounded-xl border bg-card p-4 sm:flex-row sm:items-center sm:justify-between"><div><h3 className="text-lg font-semibold">Proveedores</h3><p className="text-sm text-muted-foreground">Administra proveedores para compras e inventario avanzado.</p></div><Button onClick={() => edit()} className="gap-2"><Plus className="h-4 w-4" />Nuevo proveedor</Button></div><Input placeholder="Buscar proveedor" value={query} onChange={(e) => setQuery(e.target.value)} /><Table><TableHeader><TableRow><TableHead>Proveedor</TableHead><TableHead>Código</TableHead><TableHead>Teléfono</TableHead><TableHead>Email</TableHead><TableHead>Estado</TableHead><TableHead>Acciones</TableHead></TableRow></TableHeader><TableBody>{filtered.map((supplier) => <TableRow key={supplier.id}><TableCell>{supplier.name}</TableCell><TableCell>{supplier.code || "—"}</TableCell><TableCell>{supplier.phone || "—"}</TableCell><TableCell>{supplier.email || "—"}</TableCell><TableCell><Badge variant={supplier.isActive ? "default" : "outline"}>{supplier.isActive ? "Activo" : "Inactivo"}</Badge></TableCell><TableCell className="flex gap-2"><IconOnly label="Editar proveedor" onClick={() => edit(supplier)}><Pencil className="h-4 w-4" /></IconOnly><IconOnly label="Desactivar proveedor" onClick={() => void remove(supplier)} variant="destructive"><Trash2 className="h-4 w-4" /></IconOnly></TableCell></TableRow>)}{filtered.length === 0 ? <TableRow><TableCell colSpan={6} className="py-8 text-center text-muted-foreground">No hay proveedores.</TableCell></TableRow> : null}</TableBody></Table><Dialog open={open} onOpenChange={setOpen}><DialogContent className="max-w-2xl"><DialogHeader><DialogTitle>{draft.id ? "Editar proveedor" : "Nuevo proveedor"}</DialogTitle></DialogHeader><div className="grid gap-3 sm:grid-cols-2"><div className="space-y-1"><Label>Nombre</Label><Input value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} /></div><div className="space-y-1"><Label>Código</Label><Input value={draft.code} onChange={(e) => setDraft({ ...draft, code: e.target.value })} /></div><div className="space-y-1"><Label>Contacto</Label><Input value={draft.contactName} onChange={(e) => setDraft({ ...draft, contactName: e.target.value })} /></div><div className="space-y-1"><Label>Teléfono</Label><Input value={draft.phone} onChange={(e) => setDraft({ ...draft, phone: e.target.value })} /></div><div className="space-y-1"><Label>Email</Label><Input value={draft.email} onChange={(e) => setDraft({ ...draft, email: e.target.value })} /></div><div className="space-y-1"><Label>NIT</Label><Input value={draft.taxId} onChange={(e) => setDraft({ ...draft, taxId: e.target.value })} /></div><div className="space-y-1 sm:col-span-2"><Label>Dirección</Label><Textarea value={draft.address} onChange={(e) => setDraft({ ...draft, address: e.target.value })} /></div><div className="space-y-1 sm:col-span-2"><Label>Notas</Label><Textarea value={draft.notes} onChange={(e) => setDraft({ ...draft, notes: e.target.value })} /></div><Label className="flex items-center gap-2"><input type="checkbox" checked={draft.isActive} onChange={(e) => setDraft({ ...draft, isActive: e.target.checked })} /> Activo</Label></div><div className="flex justify-end gap-2"><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button onClick={() => void save()}>Guardar</Button></div></DialogContent></Dialog></div>;
}

function CostsPanel({ items, suppliers, reload }: { items: InventoryItem[]; suppliers: InventorySupplier[]; reload: () => Promise<void> }) {
  const [query, setQuery] = useState("");
  const [supplierFilter, setSupplierFilter] = useState("__all");
  const [editing, setEditing] = useState<InventoryItem | null>(null);
  const [draft, setDraft] = useState({ supplier: "", unitCost: "", supplierCode: "", purchaseUnit: "", factor: "1" });
  const rows = items.filter((item) => `${item.name} ${item.sku} ${item.supplierName ?? ""}`.toLowerCase().includes(query.toLowerCase())).filter((item) => supplierFilter === "__all" || (supplierFilter === "__none" ? !item.supplier : String(item.supplier) === supplierFilter) || (supplierFilter === "__nocost" ? !item.unitCost : true));
  const edit = (item: InventoryItem) => { setEditing(item); setDraft({ supplier: item.supplier ? String(item.supplier) : "", unitCost: item.unitCost ? String(item.unitCost) : "", supplierCode: item.supplierCode ?? "", purchaseUnit: item.purchaseUnit ?? "", factor: item.purchaseToInventoryFactor ? String(item.purchaseToInventoryFactor) : "1" }); };
  const save = async () => { if (!editing) return; const factor = Number(draft.factor || 1); if (factor <= 0) return toast.error("El factor debe ser mayor a 0."); await updateInventoryItem(editing.id, { name: editing.name, sku: editing.sku, unit: editing.unit, minStock: editing.minStock, maxStock: editing.maxStock, supplier: draft.supplier ? Number(draft.supplier) : null, unitCost: parseOptionalNumber(draft.unitCost), supplierCode: draft.supplierCode, purchaseUnit: draft.purchaseUnit, purchaseToInventoryFactor: factor, notes: editing.notes, isActive: editing.isActive }); toast.success("Costos actualizados."); setEditing(null); await reload(); };
  return <div className="space-y-4"><div className="rounded-xl border bg-card p-4"><h3 className="text-lg font-semibold">Costos</h3><p className="text-sm text-muted-foreground">Edita proveedor, costo y conversión sin afectar stock ni ventas.</p></div><div className="grid gap-2 sm:grid-cols-3"><Input placeholder="Buscar artículo/SKU/proveedor" value={query} onChange={(e) => setQuery(e.target.value)} /><Select value={supplierFilter} onValueChange={setSupplierFilter}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="__all">Todos</SelectItem><SelectItem value="__none">Sin proveedor</SelectItem><SelectItem value="__nocost">Sin costo</SelectItem>{suppliers.map((supplier) => <SelectItem key={supplier.id} value={String(supplier.id)}>{supplier.name}</SelectItem>)}</SelectContent></Select></div><Table><TableHeader><TableRow><TableHead>Artículo</TableHead><TableHead>SKU</TableHead><TableHead>Stock</TableHead><TableHead>Proveedor</TableHead><TableHead>Costo</TableHead><TableHead>Unidad compra</TableHead><TableHead>Factor</TableHead><TableHead>Acciones</TableHead></TableRow></TableHeader><TableBody>{rows.map((item) => <TableRow key={item.id}><TableCell>{item.name}</TableCell><TableCell>{item.sku || "—"}</TableCell><TableCell>{formatQuantity(item.currentStock)} {item.unit}</TableCell><TableCell>{item.supplierName || "—"}</TableCell><TableCell>{item.unitCost ?? "—"}</TableCell><TableCell>{item.purchaseUnit || "—"}</TableCell><TableCell>{item.purchaseToInventoryFactor ?? 1}</TableCell><TableCell><IconOnly label="Editar costos" onClick={() => edit(item)}><Pencil className="h-4 w-4" /></IconOnly></TableCell></TableRow>)}</TableBody></Table><Dialog open={Boolean(editing)} onOpenChange={(open) => !open && setEditing(null)}><DialogContent><DialogHeader><DialogTitle>Editar costos</DialogTitle></DialogHeader><div className="grid gap-3 sm:grid-cols-2"><div className="space-y-1"><Label>Proveedor</Label><Select value={draft.supplier || "__none"} onValueChange={(v) => setDraft({ ...draft, supplier: v === "__none" ? "" : v })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="__none">Sin proveedor</SelectItem>{suppliers.map((supplier) => <SelectItem key={supplier.id} value={String(supplier.id)}>{supplier.name}</SelectItem>)}</SelectContent></Select></div><div className="space-y-1"><Label>Costo por unidad</Label><Input type="number" placeholder="0" value={draft.unitCost} onChange={(e) => setDraft({ ...draft, unitCost: e.target.value })} /></div><div className="space-y-1"><Label>Código proveedor</Label><Input value={draft.supplierCode} onChange={(e) => setDraft({ ...draft, supplierCode: e.target.value })} /></div><div className="space-y-1"><Label>Unidad compra</Label><Input value={draft.purchaseUnit} onChange={(e) => setDraft({ ...draft, purchaseUnit: e.target.value })} /></div><div className="space-y-1"><Label>Factor conversión</Label><Input type="number" placeholder="1" value={draft.factor} onChange={(e) => setDraft({ ...draft, factor: e.target.value })} /></div></div><div className="flex justify-end gap-2"><Button variant="outline" onClick={() => setEditing(null)}>Cancelar</Button><Button onClick={() => void save()}>Guardar</Button></div></DialogContent></Dialog></div>;
}

type PoDraftLine = { inventoryItem: string; quantityOrdered: string; purchaseUnit: string; factor: string; unitCost: string; notes: string };
const emptyPoLine = (): PoDraftLine => ({ inventoryItem: "", quantityOrdered: "", purchaseUnit: "", factor: "1", unitCost: "", notes: "" });
function PurchaseOrdersPanel({ items, suppliers, reloadInventory, printHtml }: { items: InventoryItem[]; suppliers: InventorySupplier[]; reloadInventory: () => Promise<void>; printHtml: (title: string, html: string) => void }) {
  const [orders, setOrders] = useState<PurchaseOrder[]>([]);
  const [open, setOpen] = useState(false);
  const [receiveOrder, setReceiveOrder] = useState<PurchaseOrder | null>(null);
  const [supplier, setSupplier] = useState(""); const [paymentCategory, setPaymentCategory] = useState("cash"); const [notes, setNotes] = useState(""); const [proofReference, setProofReference] = useState(""); const [lines, setLines] = useState<PoDraftLine[]>([emptyPoLine()]);
  const [receiveLines, setReceiveLines] = useState<Record<number, string>>({}); const [updateCost, setUpdateCost] = useState(true);
  const load = async () => setOrders(await getPurchaseOrders());
  useEffect(() => { void load(); }, []);
  const selectItem = (idx: number, id: string) => { const item = items.find((row) => String(row.id) === id); setLines((prev) => prev.map((line, lineIdx) => lineIdx === idx ? { ...line, inventoryItem: id, purchaseUnit: item?.purchaseUnit || item?.unit || "unidad", factor: String(item?.purchaseToInventoryFactor || 1), unitCost: item?.unitCost ? String(item.unitCost) : "" } : line)); if (item?.supplier && !supplier) setSupplier(String(item.supplier)); };
  const save = async (approve = false) => { if (!supplier) return toast.error("Selecciona un proveedor."); const normalized = lines.filter((line) => line.inventoryItem).map((line) => ({ inventoryItem: Number(line.inventoryItem), quantityOrdered: Number(line.quantityOrdered || 0), purchaseUnit: line.purchaseUnit, purchaseToInventoryFactor: Number(line.factor || 1), unitCost: Number(line.unitCost || 0), notes: line.notes })); if (normalized.length === 0) return toast.error("Agrega al menos una línea."); if (normalized.some((line) => line.quantityOrdered <= 0 || line.purchaseToInventoryFactor <= 0 || line.unitCost < 0)) return toast.error("Revisa cantidades, factor y costos."); const order = await savePurchaseOrder({ supplier: Number(supplier), paymentCategory, notes, proofReference, lines: normalized }); if (approve) await approvePurchaseOrder(order.id); toast.success(approve ? "Orden aprobada." : "Orden guardada como borrador."); setOpen(false); await load(); };
  const approve = async (order: PurchaseOrder) => { await approvePurchaseOrder(order.id); toast.success("Orden aprobada."); await load(); };
  const cancel = async (order: PurchaseOrder) => { await cancelPurchaseOrder(order.id, "Cancelación manual"); toast.success("Orden cancelada."); await load(); };
  const receive = async () => { if (!receiveOrder) return; const payload = Object.entries(receiveLines).filter(([, qty]) => Number(qty || 0) > 0).map(([lineId, qty]) => ({ lineId: Number(lineId), quantityReceived: Number(qty) })); if (payload.length === 0) return toast.error("Ingresa al menos una cantidad a recibir."); await receivePurchaseOrder(receiveOrder.id, { lines: payload, updateUnitCost: updateCost }); toast.success("Productos recibidos correctamente."); setReceiveOrder(null); setReceiveLines({}); await load(); await reloadInventory(); };
  const statusBadge = (order: PurchaseOrder) => <Badge>{order.statusLabel}</Badge>;
  return <div className="space-y-4"><div className="flex flex-col gap-2 rounded-xl border bg-card p-4 sm:flex-row sm:items-center sm:justify-between"><div><h3 className="text-lg font-semibold">Órdenes de compra</h3><p className="text-sm text-muted-foreground">Crea, aprueba y recibe compras sin afectar stock hasta la recepción.</p></div><Button onClick={() => { setSupplier(""); setPaymentCategory("cash"); setNotes(""); setProofReference(""); setLines([emptyPoLine()]); setOpen(true); }} className="gap-2"><Plus className="h-4 w-4" />Nueva orden</Button></div><Table><TableHeader><TableRow><TableHead>Fecha</TableHead><TableHead>Código</TableHead><TableHead>Proveedor</TableHead><TableHead>Estado</TableHead><TableHead>Total</TableHead><TableHead>Recibido</TableHead><TableHead>Creado por</TableHead><TableHead>Acciones</TableHead></TableRow></TableHeader><TableBody>{orders.map((order) => <TableRow key={order.id}><TableCell>{new Date(order.createdAt).toLocaleDateString()}</TableCell><TableCell>{order.code}</TableCell><TableCell>{order.supplierName}</TableCell><TableCell>{statusBadge(order)}</TableCell><TableCell>${order.total.toFixed(2)}</TableCell><TableCell>{order.receivedPercent ?? 0}%</TableCell><TableCell>{order.createdByUsername || "—"}</TableCell><TableCell className="flex flex-wrap gap-1">{order.status === "draft" ? <IconOnly label="Aprobar" onClick={() => void approve(order)}><Check className="h-4 w-4" /></IconOnly> : null}{["approved", "partially_received"].includes(order.status) ? <IconOnly label="Recibir" onClick={() => { setReceiveOrder(order); setReceiveLines({}); }}><Play className="h-4 w-4" /></IconOnly> : null}{order.status !== "draft" ? <IconOnly label="Descargar PDF" onClick={() => downloadInventoryPdf(`/inventory/purchase-orders/${order.id}/pdf/`, `orden-compra-${order.code}.html`)}><FileText className="h-4 w-4" /></IconOnly> : null}{order.status !== "draft" ? <IconOnly label="Imprimir" onClick={() => printHtml(`Orden ${order.code}`, `<p>${order.supplierName}</p><table>${order.lines.map((line) => `<tr><td>${line.inventoryItemName}</td><td>${line.quantityOrdered}</td><td>${line.unitCost}</td></tr>`).join("")}</table>`)}><Printer className="h-4 w-4" /></IconOnly> : null}{["draft", "approved"].includes(order.status) ? <IconOnly label="Cancelar" onClick={() => void cancel(order)} variant="destructive"><X className="h-4 w-4" /></IconOnly> : null}</TableCell></TableRow>)}</TableBody></Table><Dialog open={open} onOpenChange={setOpen}><DialogContent className="max-h-[90vh] max-w-5xl overflow-auto"><DialogHeader><DialogTitle>Nueva orden de compra</DialogTitle></DialogHeader><div className="grid gap-3 sm:grid-cols-3"><div className="space-y-1"><Label>Proveedor</Label><Select value={supplier} onValueChange={setSupplier}><SelectTrigger><SelectValue placeholder="Proveedor" /></SelectTrigger><SelectContent>{suppliers.map((row) => <SelectItem key={row.id} value={String(row.id)}>{row.name}</SelectItem>)}</SelectContent></Select></div><div className="space-y-1"><Label>Categoría de pago</Label><Select value={paymentCategory} onValueChange={setPaymentCategory}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="cash">Efectivo</SelectItem><SelectItem value="transfer">Transferencia</SelectItem><SelectItem value="card">Tarjeta</SelectItem><SelectItem value="credit">Crédito</SelectItem><SelectItem value="other">Otro</SelectItem></SelectContent></Select></div><div className="space-y-1"><Label>Referencia comprobante</Label><Input value={proofReference} onChange={(e) => setProofReference(e.target.value)} /></div></div><div className="space-y-2"><Label>Líneas</Label>{lines.map((line, idx) => { const selected = items.find((item) => String(item.id) === line.inventoryItem); const equivalent = Number(line.quantityOrdered || 0) * Number(line.factor || 1); return <div key={idx} className="grid gap-2 rounded-xl border p-3 md:grid-cols-7"><Select value={line.inventoryItem} onValueChange={(value) => selectItem(idx, value)}><SelectTrigger><SelectValue placeholder="Artículo" /></SelectTrigger><SelectContent>{items.map((item) => <SelectItem key={item.id} value={String(item.id)}>{item.name}</SelectItem>)}</SelectContent></Select><Input type="number" placeholder="Cantidad" value={line.quantityOrdered} onChange={(e) => setLines((prev) => prev.map((row, i) => i === idx ? { ...row, quantityOrdered: e.target.value } : row))} /><Input placeholder="Unidad compra" value={line.purchaseUnit} onChange={(e) => setLines((prev) => prev.map((row, i) => i === idx ? { ...row, purchaseUnit: e.target.value } : row))} /><Input type="number" placeholder="Factor" value={line.factor} onChange={(e) => setLines((prev) => prev.map((row, i) => i === idx ? { ...row, factor: e.target.value } : row))} /><Input readOnly value={`${formatQuantity(equivalent)} ${selected?.unit ?? ""}`} /><Input type="number" placeholder="Costo" value={line.unitCost} onChange={(e) => setLines((prev) => prev.map((row, i) => i === idx ? { ...row, unitCost: e.target.value } : row))} /><Button variant="outline" onClick={() => setLines((prev) => prev.filter((_, i) => i !== idx))}>Quitar</Button></div>; })}<Button variant="outline" onClick={() => setLines((prev) => [...prev, emptyPoLine()])}>Agregar línea</Button></div><Label>Notas</Label><Textarea value={notes} onChange={(e) => setNotes(e.target.value)} /><div className="flex justify-end gap-2"><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button variant="outline" onClick={() => void save(false)}>Guardar borrador</Button><Button onClick={() => void save(true)}>Guardar y aprobar</Button></div></DialogContent></Dialog><Dialog open={Boolean(receiveOrder)} onOpenChange={(next) => !next && setReceiveOrder(null)}><DialogContent className="max-w-4xl"><DialogHeader><DialogTitle>Recibir productos {receiveOrder?.code}</DialogTitle></DialogHeader><div className="space-y-3">{receiveOrder?.lines.filter((line) => (line.pendingQuantity ?? 0) > 0).map((line) => <div key={line.id} className="grid gap-2 rounded-xl border p-3 md:grid-cols-6"><div className="md:col-span-2"><p className="font-medium">{line.inventoryItemName}</p><p className="text-xs text-muted-foreground">Pendiente: {formatQuantity(line.pendingQuantity)} {line.purchaseUnit}</p></div><Input type="number" placeholder="0" value={receiveLines[line.id ?? 0] ?? ""} onChange={(e) => setReceiveLines((prev) => ({ ...prev, [line.id ?? 0]: e.target.value }))} /><div className="text-sm text-muted-foreground">Equivale a {formatQuantity(Number(receiveLines[line.id ?? 0] || 0) * line.purchaseToInventoryFactor)} {line.inventoryItemUnit}</div><div className="text-sm">Costo: {line.unitCost}</div></div>)}<Label className="flex items-center gap-2"><input type="checkbox" checked={updateCost} onChange={(e) => setUpdateCost(e.target.checked)} /> Actualizar costo del artículo con el costo de esta compra</Label><div className="flex justify-end gap-2"><Button variant="outline" onClick={() => setReceiveOrder(null)}>Cancelar</Button><Button onClick={() => void receive()}>Recibir productos</Button></div></div></DialogContent></Dialog></div>;
}
